576|static void S_parser_feed(cmark_parser *parser, const unsigned char *buffer,
577|                          size_t len, bool eof) {
578|  const unsigned char *end = buffer + len;
579|  static const uint8_t repl[] = {239, 191, 189};
580|
581|  if (len > UINT_MAX - parser->total_size)
582|    parser->total_size = UINT_MAX;
583|  else
584|    parser->total_size += (int)len;
585|
586|  // Skip UTF-8 BOM if present; see #334
587|  if (parser->line_number == 0 && parser->column == 0 && len >= 3 &&
588|      *buffer == 0xEF && *(buffer + 1) == 0xBB &&
589|      *(buffer + 2) == 0xBF) {
590|    buffer += 3;
591|  } else if (parser->last_buffer_ended_with_cr && *buffer == '\n') {
592|    // skip NL if last buffer ended with CR ; see #117
593|    buffer++;
594|  }
595|
596|  parser->last_buffer_ended_with_cr = false;
597|  while (buffer < end) {
598|    const unsigned char *eol;
599|    bufsize_t chunk_len;
600|    bool process = false;
601|    for (eol = buffer; eol < end; ++eol) {
602|      if (S_is_line_end_char(*eol)) {
603|        process = true;
604|        break;
605|      }
606|      if (*eol == '\0' && eol < end) {
607|        break;
608|      }
609|    }
610|    if (eol >= end && eof) {
611|      process = true;
612|    }
613|
614|    chunk_len = (eol - buffer);
615|    if (process) {
616|      if (parser->linebuf.size > 0) {
617|        cmark_strbuf_put(&parser->linebuf, buffer, chunk_len);
618|        S_process_line(parser, parser->linebuf.ptr, parser->linebuf.size);
619|        cmark_strbuf_clear(&parser->linebuf);
620|      } else {
621|        S_process_line(parser, buffer, chunk_len);
622|      }
623|    } else {
624|      if (eol < end && *eol == '\0') {
625|        // omit NULL byte
626|        cmark_strbuf_put(&parser->linebuf, buffer, chunk_len);
627|        // add replacement character
628|        cmark_strbuf_put(&parser->linebuf, repl, 3);
629|      } else {
630|        cmark_strbuf_put(&parser->linebuf, buffer, chunk_len);
631|      }
632|    }
633|
634|    buffer += chunk_len;
635|    if (buffer < end) {
636|      if (*buffer == '\0') {
637|        // skip over NULL
638|        buffer++;
639|      } else {
640|        // skip over line ending characters
641|        if (*buffer == '\r') {
642|          buffer++;
643|          if (buffer == end)
644|            parser->last_buffer_ended_with_cr = true;
645|        }
646|        if (buffer < end && *buffer == '\n')
647|          buffer++;
648|      }
649|    }
650|  }
651|}

1272|static void S_process_line(cmark_parser *parser, const unsigned char *buffer,
1273|                           bufsize_t bytes) {
1274|  cmark_node *last_matched_container;
1275|  bool all_matched = true;
1276|  cmark_node *container;
1277|  cmark_chunk input;
1278|
1279|  if (parser->options & CMARK_OPT_VALIDATE_UTF8)
1280|    cmark_utf8proc_check(&parser->curline, buffer, bytes);
1281|  else
1282|    cmark_strbuf_put(&parser->curline, buffer, bytes);
1283|
1284|  bytes = parser->curline.size;
1285|
1286|  // ensure line ends with a newline:
1287|  if (bytes == 0 || !S_is_line_end_char(parser->curline.ptr[bytes - 1]))
1288|    cmark_strbuf_putc(&parser->curline, '\n');
1289|
1290|  parser->offset = 0;
1291|  parser->column = 0;
1292|  parser->first_nonspace = 0;
1293|  parser->first_nonspace_column = 0;
1294|  parser->thematic_break_kill_pos = 0;
1295|  parser->indent = 0;
1296|  parser->blank = false;
1297|  parser->partially_consumed_tab = false;
1298|
1299|  input.data = parser->curline.ptr;
1300|  input.len = parser->curline.size;
1301|
1302|  parser->line_number++;
1303|
1304|  last_matched_container = check_open_blocks(parser, &input, &all_matched);
1305|
1306|  if (!last_matched_container)
1307|    goto finished;
1308|
1309|  container = last_matched_container;
1310|
1311|  open_new_blocks(parser, &container, &input, all_matched);
1312|
1313|  add_text_to_container(parser, container, last_matched_container, &input);
1314|
1315|finished:
1316|  parser->last_line_length = input.len;
1317|  if (parser->last_line_length &&
1318|      input.data[parser->last_line_length - 1] == '\n')
1319|    parser->last_line_length -= 1;
1320|  if (parser->last_line_length &&
1321|      input.data[parser->last_line_length - 1] == '\r')
1322|    parser->last_line_length -= 1;
1323|
1324|  cmark_strbuf_clear(&parser->curline);
